static void slot_fill_ha(const llama_hparams & h, int64_t * a) {
    for (int i = 0; i < LLAMA_MAX_LAYERS; ++i) a[HA_N_FF_ARR_P * SLOT_AV + i] = (int64_t) h.n_ff_arr[i];
    for (int i = 0; i < LLAMA_MAX_LAYERS; ++i) a[HA_N_FF_EXP_ARR_P * SLOT_AV + i] = (int64_t) h.n_ff_exp_arr[i];
    for (int i = 0; i < LLAMA_MAX_LAYERS; ++i) a[HA_DEEPSTACK_MAPPING_ARR * SLOT_AV + i] = (int64_t) h.deepstack_mapping_arr[i];
    for (int i = 0; i < LLAMA_MAX_LAYERS; ++i) a[HA_N_HEAD_ARR_P * SLOT_AV + i] = (int64_t) h.n_head_arr[i];
    for (int i = 0; i < LLAMA_MAX_LAYERS; ++i) a[HA_N_HEAD_KV_ARR_P * SLOT_AV + i] = (int64_t) h.n_head_kv_arr[i];
    for (int i = 0; i < LLAMA_MAX_LAYERS; ++i) a[HA_ROPE_PATTERN_P * SLOT_AV + i] = (int64_t) h.rope_pattern[i];
    for (int i = 0; i < LLAMA_MAX_LAYERS; ++i) a[HA_IS_SWA_IMPL * SLOT_AV + i] = (int64_t) h.is_swa_impl[i];
    for (int i = 0; i < LLAMA_MAX_LAYERS; ++i) a[HA_IS_INDEXER_FULL_IMPL_P * SLOT_AV + i] = (int64_t) h.is_indexer_full_impl[i];
    for (int i = 0; i < LLAMA_MAX_LAYERS; ++i) a[HA_IS_RECR_IMPL_P * SLOT_AV + i] = (int64_t) h.is_recr_impl[i];
    for (int i = 0; i < LLAMA_MAX_LAYERS; ++i) a[HA_DSV4_COMPRESS_RATIOS * SLOT_AV + i] = (int64_t) h.dsv4_compress_ratios[i];
    for (int i = 0; i < LLAMA_MAX_LAYERS; ++i) a[HA_DSV4_COMPRESS_RATIOS_P * SLOT_AV + i] = (int64_t) h.dsv4_compress_ratios[i];
    for (int i = 0; i < SLOT_AV; ++i) a[HA_IS_PLE_IMPL * SLOT_AV + i] = (int64_t) h.is_ple_impl[i];
    for (int i = 0; i < LLAMA_MAX_PLE_NGRAM; ++i) a[HA_PLE_LAYER_MULTIPLIERS * SLOT_AV + i] = (int64_t) h.ple_layer_multipliers[i];
    for (int i = 0; i < LLAMA_MAX_PLE_HEADS; ++i) a[HA_PLE_HEAD_OFFSETS * SLOT_AV + i] = (int64_t) h.ple_head_offsets[i];
    for (int i = 0; i < LLAMA_MAX_PLE_HEADS; ++i) a[HA_PLE_HEAD_VOCAB_SIZES * SLOT_AV + i] = (int64_t) h.ple_head_vocab_sizes[i];
    for (int i = 0; i < 4; ++i) a[HA_ROPE_SECTIONS * SLOT_AV + i] = (int64_t) h.rope_sections[i];
}

static void slot_fill_haf(const llama_hparams & h, float * a) {
    for (int i = 0; i < LLAMA_MAX_LAYERS; ++i) a[HAF_SWIGLU_CLAMP_EXP * SLOT_AV + i] = h.swiglu_clamp_exp[i];
    for (int i = 0; i < LLAMA_MAX_LAYERS; ++i) a[HAF_SWIGLU_CLAMP_SHEXP * SLOT_AV + i] = h.swiglu_clamp_shexp[i];
    for (int i = 0; i < LLAMA_MAX_LAYERS; ++i) a[HAF_XIELU_ALPHA_N * SLOT_AV + i] = h.xielu_alpha_n[i];
    for (int i = 0; i < LLAMA_MAX_LAYERS; ++i) a[HAF_XIELU_ALPHA_P * SLOT_AV + i] = h.xielu_alpha_p[i];
    for (int i = 0; i < LLAMA_MAX_LAYERS; ++i) a[HAF_XIELU_BETA * SLOT_AV + i] = h.xielu_beta[i];
    for (int i = 0; i < LLAMA_MAX_LAYERS; ++i) a[HAF_XIELU_EPS * SLOT_AV + i] = h.xielu_eps[i];
}
